using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Threading;
using System.Web.Script.Serialization;

// Temporary-file fixtures only. ACL and stopped-VM callbacks are adapters;
// none of these cases is protected Hyper-V or installed desktop acceptance.
public static class MuSnapshotDeleteFixture {
    private const string Owner="fixture-owner-ciphertext-never-in-delete-history";
    private static readonly string Authority=new string('a',64);
    private static void Require(bool ok,string message){if(!ok)throw new Exception(message);}
    private static bool Fails(Action action){try{action();return false;}catch(IOException){return true;}catch(InvalidDataException){return true;}catch(InvalidOperationException){return true;}catch(OperationCanceledException){return true;}catch(UnauthorizedAccessException){return true;}catch(ArgumentException){return true;}}
    private static string Hash(string file){using(var input=File.OpenRead(file))using(var hash=SHA256.Create())return BitConverter.ToString(hash.ComputeHash(input));}
    private static byte[] Bytes(int length,byte value){var bytes=new byte[length];for(int i=0;i<bytes.Length;i++)bytes[i]=value;return bytes;}
    public sealed class ProcessState {public string id,snapshotId,name,boundary,diskSha256,seedSha256;}
    public static string RunProcess(string root,string mode,string boundary){
        var serializer=new JavaScriptSerializer();string stateFile=Path.Combine(root,"state.json");ProcessState state=null;
        Action<string> guard=file=>{string full=Path.GetFullPath(file);if(!full.StartsWith(Path.GetFullPath(root)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new UnauthorizedAccessException("Process fixture path changed");string next=full;while(next.Length>root.Length){if(File.Exists(next)||Directory.Exists(next))if((File.GetAttributes(next)&FileAttributes.ReparsePoint)!=0)throw new UnauthorizedAccessException("Process fixture reparse rejected");next=Path.GetDirectoryName(next);}};
        Action<string> directory=file=>{guard(file);Directory.CreateDirectory(file);};Func<string,FileStream> read=file=>{guard(file);return new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.Read);};
        Action<string,object> save=(file,value)=>{byte[] data=Encoding.UTF8.GetBytes(serializer.Serialize(value));string next=file+".next";using(var output=new FileStream(next,FileMode.CreateNew,FileAccess.Write,FileShare.None)){output.Write(data,0,data.Length);output.Flush(true);}File.Move(next,file);};
        if(mode=="prepare"){
            state=new ProcessState{id=Guid.NewGuid().ToString("D"),name="进程删除副本",boundary=boundary};string allocation=Path.Combine(root,state.id);directory(allocation);string disk=Path.Combine(allocation,"disk.vhdx"),seed=Path.Combine(allocation,"seed.iso");File.WriteAllBytes(disk,Bytes(3*1048576,31));File.WriteAllBytes(seed,Bytes(65536,41));
            var store=new MuOfflineSnapshotStore(allocation,state.id,directory,read,bytes=>{},()=>{},point=>{
                if(point!=boundary)return;save(Path.Combine(root,"ready.json"),new{pid=System.Diagnostics.Process.GetCurrentProcess().Id,id=state.id,snapshotId=state.snapshotId,boundary=point,operation="snapshot-delete-paused"});
                using(var never=new ManualResetEvent(false)){never.WaitOne(60000);}throw new TimeoutException("Fixture was not terminated at its bound deletion boundary");
            });
            var snapshot=store.Create(state.name,Owner,CancellationToken.None);state.snapshotId=snapshot.id;File.WriteAllBytes(disk,Bytes(3*1048576,81));File.WriteAllBytes(seed,Bytes(65536,82));state.diskSha256=Hash(disk);state.seedSha256=Hash(seed);save(stateFile,state);
            store.Delete(snapshot.id,snapshot.name,Authority,false,value=>Require(value.environmentId==state.id&&value.configuration==Owner,"Process owner mismatch"),CancellationToken.None);throw new InvalidOperationException("Requested process boundary not reached");
        }
        if(mode!="recover")throw new ArgumentException("Unknown process fixture mode");
        state=serializer.Deserialize<ProcessState>(File.ReadAllText(stateFile));Guid parsed;Require(Guid.TryParseExact(state.id,"D",out parsed)&&parsed.ToString("D")==state.id&&state.boundary==boundary,"Process fixture state changed");
        string target=Path.Combine(root,state.id),snapshots=Path.Combine(target,"snapshots");var resumed=new MuOfflineSnapshotStore(target,state.id,directory,read,bytes=>{},()=>{},point=>{});
        var result=resumed.Delete(state.snapshotId,state.name,Authority,true,value=>Require(value.environmentId==state.id&&value.configuration==Owner,"Resumed owner mismatch"),CancellationToken.None);
        Require(result.deleted&&result.alreadyDeleted==(boundary=="delete-completed"),"Resumed deletion receipt changed");Require(Hash(Path.Combine(target,"disk.vhdx"))==state.diskSha256&&Hash(Path.Combine(target,"seed.iso"))==state.seedSha256,"Process recovery changed live disk or seed");
        Require(!Directory.Exists(Path.Combine(snapshots,state.snapshotId))&&!Directory.Exists(Path.Combine(snapshots,"delete-active-"+state.snapshotId))&&resumed.PendingDeletions(Authority).Length==0,"Process recovery left large snapshot bytes or pending intent");Require(resumed.Delete(state.snapshotId,state.name,Authority,true,value=>{},CancellationToken.None).alreadyDeleted,"Lost final response is not idempotent");
        return serializer.Serialize(new{complete=true,pid=System.Diagnostics.Process.GetCurrentProcess().Id,id=state.id,snapshotId=state.snapshotId,boundary=boundary,alreadyDeleted=result.alreadyDeleted,liveDiskAndSeedUnchanged=true,exactSnapshotCopyRemoved=true,durableReceiptRetained=File.Exists(Path.Combine(snapshots,"delete-history",state.snapshotId+".json")),realHyperVExercised=false,protectedAclExercised=false,realDiskFullExercised=false,productSnapshotFeatureEnabled=false});
    }
    private sealed class Case {
        public string root,id,allocation,disk,seed,originalDisk,originalSeed;public bool running;public Action<string> step;public int authorized;public List<string> reads=new List<string>();
        public Case(string parent,string name){root=Path.Combine(parent,name);Directory.CreateDirectory(root);id=Guid.NewGuid().ToString("D");allocation=Path.Combine(root,id);Directory.CreateDirectory(allocation);disk=Path.Combine(allocation,"disk.vhdx");seed=Path.Combine(allocation,"seed.iso");File.WriteAllBytes(disk,Bytes(3*1048576,31));File.WriteAllBytes(seed,Bytes(65536,41));Remember();}
        private void Boundary(string file){string full=Path.GetFullPath(file);if(!full.StartsWith(Path.GetFullPath(root)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new UnauthorizedAccessException("Fixture path changed");string next=full;while(next.Length>root.Length){if(File.Exists(next)||Directory.Exists(next))if((File.GetAttributes(next)&FileAttributes.ReparsePoint)!=0)throw new UnauthorizedAccessException("Fixture reparse rejected");next=Path.GetDirectoryName(next);}}
        public MuOfflineSnapshotStore Store(){return new MuOfflineSnapshotStore(allocation,id,file=>{Boundary(file);Directory.CreateDirectory(file);},file=>{Boundary(file);reads.Add(file);return new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.Read);},bytes=>{},()=>{if(running)throw new InvalidOperationException("Fixture is running");},point=>{if(step!=null)step(point);});}
        public void Remember(){originalDisk=Hash(disk);originalSeed=Hash(seed);}
        public void Live(){Require(Hash(disk)==originalDisk&&Hash(seed)==originalSeed,"Live disk or seed was changed by snapshot deletion");}
        public MuOfflineSnapshotStore.Snapshot Snapshot(){return Store().Create("工作前备份",Owner,CancellationToken.None);}
        public string Root {get{return Path.Combine(allocation,"snapshots");}}
        public string Published(string id){return Path.Combine(Root,id);}
        public string Retired(string id){return Path.Combine(Root,"delete-active-"+id);}
        public string Intent(string id){return Path.Combine(Root,"delete-intent-"+id+".json");}
        public string Receipt(string id){return Path.Combine(Root,"delete-history",id+".json");}
        public void Authorize(MuOfflineSnapshotStore.Snapshot snapshot){Require(snapshot.environmentId==id&&snapshot.configuration==Owner,"Owner configuration was not bound");authorized++;}
        public MuOfflineSnapshotStore.DeleteReceipt Delete(MuOfflineSnapshotStore.Snapshot snapshot,bool resume){return Store().Delete(snapshot.id,snapshot.name,Authority,resume,Authorize,CancellationToken.None);}
        public void Interrupt(string point,MuOfflineSnapshotStore.Snapshot snapshot){bool reached=false;step=p=>{if(p==point){reached=true;throw new IOException("Synthetic interruption");}};Require(Fails(()=>Delete(snapshot,false)),"Interruption was ignored");step=null;Require(reached,"Requested boundary was not reached");}
        public void MutatePlan(string id,Action<Dictionary<string,object>> edit){var serializer=new JavaScriptSerializer();string file=Intent(id);var raw=serializer.Deserialize<Dictionary<string,object>>(File.ReadAllText(file));edit(raw);File.WriteAllText(file,serializer.Serialize(raw));}
        public void Copies(string dir){Require(File.Exists(Path.Combine(dir,"disk.vhdx"))&&File.Exists(Path.Combine(dir,"seed.iso"))&&File.Exists(Path.Combine(dir,"manifest.json")),"Snapshot copy was removed before complete preflight");}
    }
    public static string Run(string parent){
        var results=new List<object>();Action<string,Action<Case>> test=(name,run)=>{var c=new Case(parent,name);try{run(c);c.Live();}catch(Exception error){throw new Exception("Snapshot deletion case "+name+": "+error.Message,error);}results.Add(new{name=name,passed=true});};
        test("delete-only-exact-snapshot-copy-and-return-durable-receipt",c=>{
            var snapshot=c.Snapshot();var other=c.Snapshot();File.WriteAllBytes(c.disk,Bytes(3*1048576,81));File.WriteAllBytes(c.seed,Bytes(65536,82));c.Remember();c.reads.Clear();File.WriteAllText(Path.Combine(c.Root,"unrelated-user-note.txt"),"keep");
            var result=c.Delete(snapshot,false);Require(result.deleted&&!result.alreadyDeleted&&result.id==snapshot.id&&result.environmentId==c.id&&result.name==snapshot.name&&result.bytes==3*1048576+65536,"Deletion receipt changed");Require(!Directory.Exists(c.Published(snapshot.id))&&!Directory.Exists(c.Retired(snapshot.id))&&!File.Exists(c.Intent(snapshot.id))&&File.Exists(c.Receipt(snapshot.id)),"Snapshot bytes or intent were not reclaimed");c.Copies(c.Published(other.id));Require(File.ReadAllText(Path.Combine(c.Root,"unrelated-user-note.txt"))=="keep","Unrelated root file changed");Require(c.reads.All(file=>file!=c.disk&&file!=c.seed),"Deletion opened a live disk or seed");Require(!File.ReadAllText(c.Receipt(snapshot.id)).Contains(Owner),"Delete history leaked owner ciphertext");Require(c.Delete(snapshot,true).alreadyDeleted,"Lost final response could not be retried");
        });
        foreach(string boundary in new[]{"delete-intent-published","delete-retired","delete-removed-disk","delete-removed-seed","delete-removed-manifest","delete-folder-removed","delete-completed"}){
            string point=boundary;test("resume-"+point,c=>{
                var snapshot=c.Snapshot();c.Interrupt(point,snapshot);Require(c.Store().List().Length==0,"Deleting snapshot was still published");Require(Fails(()=>c.Store().Get(snapshot.id)),"Deleting snapshot could be read as restorable");Require(Fails(()=>c.Store().PrepareRestore(snapshot.id,Owner,CancellationToken.None)),"Deleting snapshot could be restored");
                if(point!="delete-completed"){var pending=c.Store().PendingDeletions(Authority);Require(pending.Length==1&&pending[0].id==snapshot.id&&pending[0].name==snapshot.name,"Pending deletion identity lost");}
                var resumed=c.Delete(snapshot,true);Require(resumed.deleted&&resumed.alreadyDeleted==(point=="delete-completed"),"Deletion resume chose wrong receipt");Require(c.Store().PendingDeletions(Authority).Length==0&&!Directory.Exists(c.Retired(snapshot.id)),"Deletion resume retained large snapshot files");Require(c.Delete(snapshot,true).alreadyDeleted,"Repeated resume was not idempotent");
            });
        }
        test("resume-only-cannot-begin-new-deletion",c=>{var snapshot=c.Snapshot();Require(Fails(()=>c.Delete(snapshot,true)),"Resume-only began a deletion");Require(!File.Exists(c.Intent(snapshot.id)),"Resume-only published intent");c.Copies(c.Published(snapshot.id));});
        test("exact-name-required-before-intent",c=>{var snapshot=c.Snapshot();Require(Fails(()=>c.Store().Delete(snapshot.id,"错误名称",Authority,false,c.Authorize,CancellationToken.None)),"Wrong name admitted");Require(!File.Exists(c.Intent(snapshot.id)),"Wrong name published intent");c.Copies(c.Published(snapshot.id));});
        test("owner-envelope-authority-required",c=>{var snapshot=c.Snapshot();Require(Fails(()=>c.Store().Delete(snapshot.id,snapshot.name,Authority,false,value=>{throw new UnauthorizedAccessException("Synthetic owner mismatch");},CancellationToken.None)),"Invalid owner admitted");Require(!File.Exists(c.Intent(snapshot.id)),"Unverified owner published intent");c.Copies(c.Published(snapshot.id));});
        test("unknown-snapshot-is-not-success",c=>{Require(Fails(()=>c.Store().Delete(Guid.NewGuid().ToString("D"),"未知",Authority,false,c.Authorize,CancellationToken.None)),"Unknown identity reported deleted");Require(Fails(()=>c.Store().Delete("../outside","未知",Authority,false,c.Authorize,CancellationToken.None)),"Path-like identity admitted");});
        test("pending-intent-bound-to-original-owner-vm-authority",c=>{var snapshot=c.Snapshot();c.Interrupt("delete-retired",snapshot);Require(Fails(()=>c.Store().Delete(snapshot.id,snapshot.name,new string('b',64),true,c.Authorize,CancellationToken.None)),"Different VM authority resumed intent");Require(Fails(()=>c.Store().PendingDeletions(new string('b',64))),"Different authority could inspect deletion");c.Copies(c.Retired(snapshot.id));});
        test("pending-name-cannot-be-substituted",c=>{var snapshot=c.Snapshot();c.Interrupt("delete-retired",snapshot);Require(Fails(()=>c.Store().Delete(snapshot.id,"替换名称",Authority,true,c.Authorize,CancellationToken.None)),"Different confirmation resumed deletion");c.Copies(c.Retired(snapshot.id));});
        test("active-restore-blocks-deletion",c=>{var snapshot=c.Snapshot();var restore=c.Store().PrepareRestore(snapshot.id,Owner,CancellationToken.None);c.Remember();Require(Fails(()=>c.Delete(snapshot,false)),"Pending restore allowed deletion");Require(c.Store().Pending().id==restore.id&&!File.Exists(c.Intent(snapshot.id)),"Deletion changed restore authority");c.Copies(c.Published(snapshot.id));});
        test("archived-restore-decision-does-not-depend-on-deleted-copy",c=>{var snapshot=c.Snapshot();var restore=c.Store().PrepareRestore(snapshot.id,Owner,CancellationToken.None);c.Store().CommitRestore(restore.id);c.Store().AcknowledgeRestore(restore.id);c.Remember();string history=Path.Combine(c.Root,"restore-history",restore.id),journal=Hash(Path.Combine(history,"journal.json")),rollback=Hash(Path.Combine(history,"disk.rollback"));c.Delete(snapshot,false);var outcome=c.Store().History(restore.id);Require(outcome.snapshotId==snapshot.id&&outcome.phase=="committed"&&Hash(Path.Combine(history,"journal.json"))==journal&&Hash(Path.Combine(history,"disk.rollback"))==rollback,"Deletion modified acknowledged recovery history");});
        test("entire-source-preflight-before-first-remove",c=>{var snapshot=c.Snapshot();string dir=c.Published(snapshot.id);File.WriteAllBytes(Path.Combine(dir,"seed.iso"),Bytes(65536,99));Require(Fails(()=>c.Delete(snapshot,false)),"Corrupt later file admitted");c.Copies(dir);Require(!File.Exists(c.Intent(snapshot.id)),"Corrupt source published deletion intent");});
        test("entire-retired-preflight-before-resuming-removal",c=>{var snapshot=c.Snapshot();c.Interrupt("delete-retired",snapshot);File.WriteAllBytes(Path.Combine(c.Retired(snapshot.id),"seed.iso"),Bytes(65536,99));Require(Fails(()=>c.Delete(snapshot,true)),"Corrupt retired file admitted");c.Copies(c.Retired(snapshot.id));});
        test("unknown-source-file-preserved",c=>{var snapshot=c.Snapshot();string dir=c.Published(snapshot.id);File.WriteAllText(Path.Combine(dir,"private.txt"),"keep");Require(Fails(()=>c.Delete(snapshot,false)),"Unknown source file admitted");c.Copies(dir);Require(File.ReadAllText(Path.Combine(dir,"private.txt"))=="keep"&&!File.Exists(c.Intent(snapshot.id)),"Unknown source file removed");});
        test("unknown-retired-directory-preserves-all-remaining-files",c=>{var snapshot=c.Snapshot();c.Interrupt("delete-retired",snapshot);string extra=Path.Combine(c.Retired(snapshot.id),"unknown-child");Directory.CreateDirectory(extra);File.WriteAllText(Path.Combine(extra,"keep.txt"),"keep");Require(Fails(()=>c.Delete(snapshot,true)),"Unknown directory recursively removed");c.Copies(c.Retired(snapshot.id));Require(File.ReadAllText(Path.Combine(extra,"keep.txt"))=="keep","Unknown directory content changed");});
        test("new-unknown-content-stops-subsequent-removals",c=>{var snapshot=c.Snapshot();c.step=point=>{if(point=="delete-removed-disk")File.WriteAllText(Path.Combine(c.Retired(snapshot.id),"late.txt"),"keep");};Require(Fails(()=>c.Delete(snapshot,false)),"Late unknown content ignored");c.step=null;Require(File.Exists(Path.Combine(c.Retired(snapshot.id),"seed.iso"))&&File.Exists(Path.Combine(c.Retired(snapshot.id),"manifest.json")),"Remaining known files removed after unknown content appeared");});
        test("missing-manifest-before-data-removal-preserves-data",c=>{var snapshot=c.Snapshot();c.Interrupt("delete-retired",snapshot);File.Delete(Path.Combine(c.Retired(snapshot.id),"manifest.json"));Require(Fails(()=>c.Delete(snapshot,true)),"Missing manifest admitted");Require(File.Exists(Path.Combine(c.Retired(snapshot.id),"disk.vhdx"))&&File.Exists(Path.Combine(c.Retired(snapshot.id),"seed.iso")),"Data removed without manifest");});
        foreach(string fault in new[]{"extra","type","environment","digest","files"}){string kind=fault;test("strict-delete-intent-"+kind,c=>{var snapshot=c.Snapshot();c.Interrupt("delete-retired",snapshot);c.MutatePlan(snapshot.id,raw=>{if(kind=="extra")raw["path"]="outside";else if(kind=="type")raw["manifestBytes"]="123";else if(kind=="environment")raw["environmentId"]=Guid.NewGuid().ToString("D");else if(kind=="digest")raw["manifestSha256"]=new string('z',64);else raw["files"]=new object[0];});Require(Fails(()=>c.Delete(snapshot,true)),"Changed plan admitted");c.Copies(c.Retired(snapshot.id));});}
        test("separate-instance-cannot-bypass-operation-lock",c=>{var snapshot=c.Snapshot();bool attempted=false;c.step=point=>{if(point=="delete-retired"){attempted=true;Require(Fails(()=>c.Delete(snapshot,true)),"Concurrent store bypassed deletion lock");}};c.Delete(snapshot,false);c.step=null;Require(attempted,"Concurrent operation was not attempted");});
        test("cancel-after-first-remove-remains-explicitly-resumable",c=>{var snapshot=c.Snapshot();var cancel=new CancellationTokenSource();c.step=point=>{if(point=="delete-removed-disk")cancel.Cancel();};Require(Fails(()=>c.Store().Delete(snapshot.id,snapshot.name,Authority,false,c.Authorize,cancel.Token)),"Cancellation ignored");c.step=null;Require(File.Exists(Path.Combine(c.Retired(snapshot.id),"seed.iso"))&&File.Exists(c.Intent(snapshot.id)),"Cancelled deletion lost remaining file or intent");Require(c.Delete(snapshot,true).deleted,"Cancelled deletion could not resume");});
        test("running-initially-or-after-retirement-stops-removal",c=>{var snapshot=c.Snapshot();c.running=true;Require(Fails(()=>c.Delete(snapshot,false)),"Running environment admitted");c.running=false;c.Copies(c.Published(snapshot.id));c.step=point=>{if(point=="delete-retired")c.running=true;};Require(Fails(()=>c.Delete(snapshot,false)),"Running-after-retirement admitted");c.step=null;c.Copies(c.Retired(snapshot.id));c.running=false;c.Delete(snapshot,true);});
        test("duplicate-published-and-retired-copies-retained",c=>{var snapshot=c.Snapshot();c.Interrupt("delete-retired",snapshot);Directory.CreateDirectory(c.Published(snapshot.id));foreach(string file in Directory.GetFiles(c.Retired(snapshot.id)))File.Copy(file,Path.Combine(c.Published(snapshot.id),Path.GetFileName(file)));Require(Fails(()=>c.Delete(snapshot,true)),"Conflicting directories guessed");c.Copies(c.Published(snapshot.id));c.Copies(c.Retired(snapshot.id));});
        test("changed-source-after-intent-is-not-retired",c=>{var snapshot=c.Snapshot();c.Interrupt("delete-intent-published",snapshot);File.WriteAllBytes(Path.Combine(c.Published(snapshot.id),"seed.iso"),Bytes(65536,99));Require(Fails(()=>c.Delete(snapshot,true)),"Changed source retired");c.Copies(c.Published(snapshot.id));Require(!Directory.Exists(c.Retired(snapshot.id)),"Changed source was moved");});
        test("unregistered-retired-directory-is-not-adopted",c=>{var snapshot=c.Snapshot();Directory.Move(c.Published(snapshot.id),c.Retired(snapshot.id));Require(Fails(()=>c.Delete(snapshot,false)),"Unregistered retired content adopted");c.Copies(c.Retired(snapshot.id));Require(!File.Exists(c.Intent(snapshot.id)),"Unregistered content acquired deletion authority");});
        test("retired-snapshot-still-counts-toward-limit",c=>{var snapshot=c.Snapshot();for(int i=1;i<32;i++)c.Snapshot();c.Interrupt("delete-retired",snapshot);Require(Fails(()=>c.Snapshot()),"Retired data escaped snapshot count limit");Require(c.Store().List().Length==31,"Retirement changed unrelated catalog entries");});
        return new JavaScriptSerializer().Serialize(new {complete=true,checks=results,realFileSystemExercised=true,actualProcessTerminationExercised=false,realHyperVExercised=false,protectedAclExercised=false,realDiskFullExercised=false,productSnapshotFeatureEnabled=false});
    }
}
